            return []
        mapping = {'2':'abc','3':'def','4':'ghi','5':'jkl','6':'mno','7':'pqrs','8':'tuv','9':'wxyz'}
        res = []
        def backtrack(idx, path):
            if idx == len(digits):
                res.append(''.join(path))
                return
